function isMonotonic(nums) {
  // Monotonic means the array already equals one of its two sorted orders.
  const up = [...nums].sort((a, b) => a - b);
  const down = [...up].reverse();
  const same = (other) => other.every((v, k) => v === nums[k]);
  return same(up) || same(down);
}

