function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 6);
  const span = size === 'large' ? 100000 : 1 + Math.floor(rand() * 4);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  const shape = Math.floor(rand() * 5);
  if (shape === 0) nums.sort((a, b) => a - b);
  else if (shape === 1) nums.sort((a, b) => b - a);
  else if (shape === 2 || shape === 3) {
    // Sorted in one direction, then one neighbouring pair swapped (usually breaking the order).
    nums.sort(shape === 2 ? (a, b) => a - b : (a, b) => b - a);
    if (n >= 2) {
      const k = Math.floor(rand() * (n - 1));
      [nums[k], nums[k + 1]] = [nums[k + 1], nums[k]];
    }
  }
  return [nums];
}
